-- Phase 36.4 (the guardrails review's L4): a client request's contact is one on the request's own
-- contract, held by the database as well as the code (src/lib/client/requests.ts takes both from
-- the contact's row). Generated by drizzle-kit, then by hand: these comments, and the unique key
-- moved first (the foreign key needs it).
-- - client_contacts: unique (firm_id, contract_id, id), for the composite key below.
-- - client_requests_contact_fk: now (firm_id, contract_id, client_contact_id) ->
--   client_contacts (firm_id, contract_id, id), still ON DELETE CASCADE. Every request already
--   stored was made with its contact's own contract, so the new key holds for them all.
ALTER TABLE "client_contacts" ADD CONSTRAINT "client_contacts_firm_id_contract_id_id_key" UNIQUE("firm_id","contract_id","id");--> statement-breakpoint
ALTER TABLE "client_requests" DROP CONSTRAINT "client_requests_contact_fk";--> statement-breakpoint
ALTER TABLE "client_requests" ADD CONSTRAINT "client_requests_contact_fk" FOREIGN KEY ("firm_id","contract_id","client_contact_id") REFERENCES "public"."client_contacts"("firm_id","contract_id","id") ON DELETE cascade ON UPDATE no action;
